/* DAWAH X — ahmad, অধ্যায় 10 · খণ্ড 10 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][10]=[[1801,1801,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏لَمْ أَحْفَظْ عَنْهُ غَيْرَهُ ‏ ‏قَالَ سَمِعْتُهُ عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَشَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السِّتَارَةِ وَالنَّاسُ صُفُوفٌ خَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَ أَيُّهَا النَّاسُ إِنَّهُ ‏ ‏لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الْمُسْلِمُ أَوْ تُرَى لَهُ ثُمَّ قَالَ أَلَا إِنِّي نُهِيتُ أَنْ أَقْرَأَ رَاكِعًا أَوْ سَاجِدًا فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ ‏ ‏فَقَمِنٌ ‏ ‏أَنْ يُسْتَجَابَ لَكُمْ ‏","","",""],[1802,1802,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُعَذِّبُوا بِعَذَابِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[1803,1803,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى قَبْلَ الْخُطْبَةِ فِي الْعِيدِ ثُمَّ خَطَبَ فَرَأَى أَنَّهُ لَمْ يُسْمِعْ النِّسَاءَ فَأَتَاهُنَّ فَذَكَّرَهُنَّ وَوَعَظَهُنَّ وَأَمَرَهُنَّ ‏ ‏بِالصَّدَقَةِ ‏ ‏فَجَعَلَتْ الْمَرْأَةُ ‏ ‏تُلْقِي ‏ ‏الْخُرْصَ ‏ ‏وَالْخَاتَمَ وَالشَّيْءَ ‏","","",""],[1804,1804,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ مِنْ دَلْوٍ مِنْ ‏ ‏زَمْزَمَ ‏ ‏قَائِمًا ‏ ‏قَالَ ‏ ‏سَفْيَانُ ‏ ‏كَذَا أَحْسَبُ ‏","","",""],[1805,1805,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏شَرِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏عَنْ يَمِينِهِ ‏ ‏وَخَالِدُ بْنُ الْوَلِيدِ ‏ ‏عَنْ شِمَالِهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّرْبَةُ لَكَ وَإِنْ شِئْتَ ‏ ‏آثَرْتَ ‏ ‏بِهَا ‏ ‏خَالِدًا ‏ ‏قَالَ مَا ‏ ‏أُوثِرُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدًا ‏","","",""],[1806,1806,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏يَعْنِي ‏ ‏اسْتَأْذَنَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَلَمْ يَزَلْ بِهَا بَنُو أَخِيهَا قَالَتْ أَخَافُ أَنْ يُزَكِّيَنِي فَلَمَّا أَذِنَتْ لَهُ قَالَ مَا بَيْنَكِ وَبَيْنَ أَنْ تَلْقَيْ الْأَحِبَّةَ إِلَّا أَنْ يُفَارِقَ الرُّوحُ الْجَسَدَ ‏ ‏كُنْتِ أَحَبَّ أَزْوَاجِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ وَلَمْ يَكُنْ يُحِبُّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا طَيِّبًا وَسَقَطَتْ قِلَادَتُكِ لَيْلَةَ ‏ ‏الْأَبْوَاءِ ‏ ‏فَنَزَلَتْ فِيكِ آيَاتٌ مِنْ الْقُرْآنِ فَلَيْسَ مَسْجِدٌ مِنْ مَسَاجِدِ الْمُسْلِمِينَ إِلَّا يُتْلَى فِيهِ عُذْرُكِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ فَقَالَتْ دَعْنِي مِنْ تَزْكِيَتِكَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَوَاللَّهِ لَوَدِدْتُ ‏","","",""],[1807,1807,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ لَهَا ‏ ‏إِنَّمَا سُمِّيتِ أُمَّ الْمُؤْمِنِينَ لِتَسْعَدِي وَإِنَّهُ لَاسْمُكِ قَبْلَ أَنْ تُولَدِي ‏","","",""],[1808,1808,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُتَنَفَّسَ فِي الْإِنَاءِ أَوْ يُنْفَخَ فِيهِ ‏","","",""],[1809,1809,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنَّ أَحَدَهُمْ إِذَا ‏ ‏أَتَى ‏ ‏أَهْلَهُ قَالَ بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنِي الشَّيْطَانَ وَجَنِّبْ الشَّيْطَانَ مَا رَزَقْتَنَا فَقُضِيَ بَيْنَهُمَا وَلَدٌ مَا ضَرَّهُ الشَّيْطَانُ ‏","","",""],[1810,1810,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ رُفَيْعٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَشَدَّادُ بْنُ مَعْقِلٍ ‏ ‏عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مَا بَيْنَ هَذَيْنِ اللَّوْحَيْنِ ‏ ‏وَدَخَلْنَا عَلَى ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏فَقَالَ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏الْمُخْتَارُ ‏ ‏يَقُولُ الْوَحْيُ ‏","","",""],[1811,1811,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏مُوسَى بْنُ أَبِي عَائِشَةَ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كَانَ إِذَا نَزَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرْآنٌ يُرِيدُ أَنْ يَحْفَظَهُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ ‏}","","",""],[1812,1812,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمَّا صَلَّى رَكْعَتَيْ الْفَجْرِ اضْطَجَعَ حَتَّى ‏ ‏نَفَخَ ‏ ‏فَكُنَّا نَقُولُ ‏ ‏لِعَمْرٍو ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي ‏","","",""],[1813,1813,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِتُّ عِنْدَ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ قَالَ ‏ ‏فَتَوَضَّأَ وُضُوءًا خَفِيفًا فَقَامَ فَصَنَعَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كَمَا صَنَعَ ثُمَّ جَاءَ فَقَامَ فَصَلَّى فَحَوَّلَهُ فَجَعَلَهُ عَنْ يَمِينِهِ ثُمَّ صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ اضْطَجَعَ حَتَّى ‏ ‏نَفَخَ ‏ ‏فَأَتَاهُ الْمُؤَذِّنُ ثُمَّ قَامَ إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ ‏","","",""],[1814,1814,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏إِنَّكُمْ مُلَاقُو اللَّهِ حُفَاةً عُرَاةً مُشَاةً ‏ ‏غُرْلًا ‏","","",""],[1815,1815,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَّ ‏ ‏رَجُلٌ عَنْ بَعِيرِهِ ‏ ‏فَوُقِصَ ‏ ‏فَمَاتَ وَهُوَ مُحْرِمٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَسِّلُوهُ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏ ‏وَادْفِنُوهُ فِي ثَوْبَيْهِ وَلَا ‏ ‏تُخَمِّرُوا ‏ ‏رَأْسَهُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْعَثُهُ يَوْمَ الْقِيَامَةِ مُهِلًّا ‏ ‏وَقَالَ مَرَّةً ‏ ‏يُهِلُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَلَا تُقَرِّبُوهُ طِيبًا ‏","","",""],[1816,1816,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏وَمَا جَعَلْنَا الرُّؤْيَا الَّتِي أَرَيْنَاكَ إِلَّا فِتْنَةً لِلنَّاسِ ‏} ‏قَالَ هِيَ رُؤْيَا عَيْنٍ رَآهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِهِ ‏","","",""],[1817,1817,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ يَقُولُ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَمَنْ لَمْ يَجِدْ ‏ ‏إِزَارًا ‏ ‏فَلْيَلْبَسْ سَرَاوِيلَ ‏","","",""],[1818,1818,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏أَخْبَرَنِي ‏ ‏جَابِرُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِيًا جَمِيعًا وَسَبْعًا جَمِيعًا ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ يَا ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أَظُنُّهُ أَخَّرَ الظُّهْرَ وَعَجَّلَ الْعَصْرَ وَأَخَّرَ الْمَغْرِبَ وَعَجَّلَ الْعِشَاءَ قَالَ وَأَنَا أَظُنَّ ذَلِكَ ‏","","",""],[1819,1819,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏قَالَ ‏ ‏أَبُو الشَّعْثَاءِ ‏ ‏مَنْ هِيَ قَالَ قُلْتُ يَقُولُونَ ‏ ‏مَيْمُونَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَكَحَ ‏ ‏مَيْمُونَةَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[1820,1820,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَا مِمَّنْ قَدَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فِي ‏ ‏ضَعَفَةِ ‏ ‏أَهْلِهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدَّمَ ‏ ‏ضَعَفَةَ ‏ ‏أَهْلِهِ ‏","","",""],[1821,1821,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِنَّمَا ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَوْلَ ‏ ‏الْكَعْبَةِ ‏ ‏لِيُرِيَ الْمُشْرِكِينَ قُوَّتَهُ ‏","","",""],[1822,1822,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏أَوَّلًا فَحَفِظْنَا ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنِي ‏ ‏طَاوُسٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَدْ ‏ ‏حَدَّثَنَاهُ ‏ ‏سُفْيَانُ ‏ ‏وَقَالَ ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَطَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ ‏ ‏مُحْرِمٌ ‏","","",""],[1823,1823,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و قَالَ ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَهَا ‏ ‏أَوْ يُلْعِقَهَا ‏","","",""],[1824,1824,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَيْسَ ‏ ‏الْمُحَصَّبُ ‏ ‏بِشَيْءٍ إِنَّمَا هُوَ مَنْزِلٌ نَزَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1825,1825,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَّرَهَا حَتَّى ذَهَبَ مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ نَامَ النِّسَاءُ وَالْوِلْدَانُ فَخَرَجَ فَقَالَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ أَنْ يُصَلُّوهَا هَذِهِ السَّاعَةَ ‏","","",""],[1826,1826,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعٍ وَنُهِيَ أَنْ ‏ ‏يَكُفَّ ‏ ‏شَعَرَهُ وَثِيَابَهُ ‏","","",""],[1827,1827,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَّا الَّذِي نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبَاعَ حَتَّى يُقْبَضَ فَالطَّعَامُ ‏ ‏و قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بِرَأْيِهِ ‏ ‏وَلَا أَحْسَبُ كُلَّ شَيْءٍ إِلَّا مِثْلَهُ ‏","","",""],[1828,1828,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُثْمَانَ بْنِ صَفْوَانَ بْنِ أُمَيَّةَ الْجُمَحِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏الْحَكَمُ بْنُ أَبَانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْمَدِينَةِ ‏ ‏مُقِيمًا غَيْرَ مُسَافِرٍ سَبْعًا وَثَمَانِيًا ‏","","",""],[1829,1829,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَوْسَجَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَجُلٌ مَاتَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَتْرُكْ وَارِثًا إِلَّا عَبْدًا هُوَ أَعْتَقَهُ فَأَعْطَاهُ مِيرَاثَهُ ‏","","",""],[1830,1830,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ حُنَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَجِبْتُ مِمَّنْ يَتَقَدَّمُ الشَّهْرَ وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْهُ ‏ ‏أَوْ قَالَ صُومُوا لِرُؤْيَتِهِ ‏","","",""],[1831,1831,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحُوَيْرِثِ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى ‏ ‏الْغَائِطَ ‏ ‏ثُمَّ خَرَجَ فَدَعَا بِالطَّعَامِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً فَأُتِيَ بِالطَّعَامِ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ أَلَا تَوَضَّأُ قَالَ لَمْ أُصَلِّ فَأَتَوَضَّأَ ‏","","",""],[1832,1832,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي مَعْبَدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا كُنْتُ أَعْرِفُ ‏ ‏انْقِضَاءَ ‏ ‏صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا بِالتَّكْبِيرِ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏قُلْتُ لَهُ حَدَّثْتَنِي قَالَ لَا مَا حَدَّثْتُكَ بِهِ ‏","","",""],[1833,1833,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي مَعْبَدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ وَلَا تُسَافِرُ امْرَأَةٌ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ وَجَاءَ رَجُلٌ فَقَالَ إِنَّ امْرَأَتِي خَرَجَتْ إِلَى الْحَجِّ وَإِنِّي اكْتَتَبْتُ فِي غَزْوَةِ كَذَا وَكَذَا قَالَ انْطَلِقْ فَاحْجُجْ مَعَ امْرَأَتِكَ ‏","","",""],[1834,1834,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ أَبِي مُسْلِمٍ ‏ ‏خَالِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏سَمِعَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَوْمُ الْخَمِيسِ وَمَا يَوْمُ الْخَمِيسِ ثُمَّ بَكَى حَتَّى بَلَّ دَمْعُهُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً دُمُوعُهُ ‏ ‏الْحَصَى قُلْنَا يَا ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏وَمَا يَوْمُ الْخَمِيسِ قَالَ اشْتَدَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَعُهُ فَقَالَ ‏ ‏ائْتُونِي أَكْتُبْ لَكُمْ كِتَابًا لَا تَضِلُّوا بَعْدَهُ أَبَدًا فَتَنَازَعُوا وَلَا يَنْبَغِي عِنْدَ نَبِيٍّ تَنَازُعٌ فَقَالُوا مَا شَأْنُهُ ‏ ‏أَهَجَرَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏يَعْنِي هَذَى ‏ ‏اسْتَفْهِمُوهُ فَذَهَبُوا يُعِيدُونَ عَلَيْهِ فَقَالَ دَعُونِي فَالَّذِي أَنَا فِيهِ خَيْرٌ مِمَّا تَدْعُونِي إِلَيْهِ وَأَمَرَ بِثَلَاثٍ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَوْصَى بِثَلَاثٍ ‏ ‏قَالَ أَخْرِجُوا الْمُشْرِكِينَ مِنْ ‏ ‏جَزِيرَةِ الْعَرَبِ ‏ ‏وَأَجِيزُوا ‏ ‏الْوَفْدَ بِنَحْوِ مَا كُنْتُ ‏ ‏أُجِيزُهُمْ ‏ ‏وَسَكَتَ ‏ ‏سَعِيدٌ ‏ ‏عَنْ الثَّالِثَةِ فَلَا أَدْرِي أَسَكَتَ عَنْهَا عَمْدًا وَقَالَ مَرَّةً أَوْ نَسِيَهَا ‏ ‏و قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏وَإِمَّا أَنْ يَكُونَ تَرَكَهَا أَوْ نَسِيَهَا ‏","","",""],[1835,1835,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏كَانَ النَّاسُ يَنْصَرِفُونَ فِي كُلِّ وَجْهٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْفِرُ أَحَدٌ حَتَّى يَكُونَ آخِرُ عَهْدِهِ ‏ ‏بِالْبَيْتِ ‏","","",""],[1836,1836,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَهُمْ ‏ ‏يُسَلِّفُونَ ‏ ‏فِي التَّمْرِ السَّنَتَيْنِ وَالثَّلَاثَ فَقَالَ ‏ ‏مَنْ ‏ ‏سَلَّفَ ‏ ‏فَلْيُسَلِّفْ ‏ ‏فِي كَيْلٍ مَعْلُومٍ وَوَزْنٍ مَعْلُومٍ إِلَى ‏ ‏أَجَلٍ ‏ ‏مَعْلُومٍ ‏","","",""],[1837,1837,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي يَزِيدَ ‏ ‏مُنْذُ سَبْعِينَ سَنَةً ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَا عَلِمْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَامَ يَوْمًا ‏ ‏يَتَحَرَّى ‏ ‏فَضْلَهُ عَلَى الْأَيَّامِ غَيْرَ يَوْمِ ‏ ‏عَاشُورَاءَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أُخْرَى إِلَّا هَذَا الْيَوْمَ ‏ ‏يَعْنِي ‏ ‏عَاشُورَاءَ ‏ ‏وَهَذَا الشَّهْرَ شَهْرَ رَمَضَانَ ‏","","",""],[1838,1838,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَنَا مِمَّنْ قَدَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةَ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فِي ‏ ‏ضَعَفَةِ ‏ ‏أَهْلِهِ ‏","","",""],[1839,1839,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أُمِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعٍ وَنُهِيَ أَنْ ‏ ‏يَكُفَّ ‏ ‏شَعْرًا أَوْ ثَوْبًا ‏","","",""],[1840,1840,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏سُئِلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ رَجُلٍ قَتَلَ مُؤْمِنًا ثُمَّ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى قَالَ ‏ ‏وَيْحَكَ ‏ ‏وَأَنَّى لَهُ الْهُدَى سَمِعْتُ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَجِيءُ الْمَقْتُولُ مُتَعَلِّقًا بِالْقَاتِلِ يَقُولُ يَا رَبِّ سَلْ هَذَا فِيمَ قَتَلَنِي ‏ ‏وَاللَّهِ لَقَدْ أَنْزَلَهَا اللَّهُ عَزَّ وَجَلَّ عَلَى نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا ‏ ‏نَسَخَهَا ‏ ‏بَعْدَ إِذْ أَنْزَلَهَا قَالَ ‏ ‏وَيْحَكَ ‏ ‏وَأَنَّى لَهُ الْهُدَى ‏","","",""],[1841,1841,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏ابْنِ مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ فِي قَمِيصِهِ الَّذِي مَاتَ فِيهِ وَحُلَّةٍ نَجْرَانِيَّةٍ الْحُلَّةُ ثَوْبَانِ ‏","","",""],[1842,1842,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏أَنْبَأَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏وَهُوَ صَائِمٌ مُحْرِمٌ ‏","","",""],[1843,1843,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْمُكَاتَبِ ‏ ‏يَعْتِقُ مِنْهُ بِقَدْرِ مَا أَدَّى دِيَةَ الْحُرِّ وَبِقَدْرِ مَا رَقَّ مِنْهُ دِيَةَ الْعَبْدِ ‏","","",""],[1844,1844,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏حَدَّثَنِي ‏ ‏عَمَّارٌ ‏ ‏مَوْلَى ‏ ‏بَنِي هِشَامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ خَمْسٍ وَسِتِّينَ سَنَةً ‏","","",""],[1845,1845,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏آخِرُ شِدَّةٍ يَلْقَاهَا الْمُؤْمِنُ الْمَوْتُ وَفِي قَوْلِهِ ‏ { ‏يَوْمَ تَكُونُ السَّمَاءُ ‏ ‏كَالْمُهْلِ ‏ } ‏قَالَ ‏ ‏كَدُرْدِيِّ ‏ ‏الزَّيْتِ وَفِي قَوْلِهِ ‏ { ‏آنَاءَ ‏ ‏اللَّيْلِ ‏} ‏قَالَ ‏ ‏جَوْفُ ‏ ‏اللَّيْلِ وَقَالَ هَلْ تَدْرُونَ مَا ذَهَابُ الْعِلْمِ قَالَ هُوَ ذَهَابُ الْعُلَمَاءِ مِنْ الْأَرْضِ ‏","","",""],[1846,1846,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ الَّذِي لَيْسَ فِي جَوْفِهِ شَيْءٌ مِنْ الْقُرْآنِ كَالْبَيْتِ الْخَرِبِ ‏","","",""],[1847,1847,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏ثُمَّ ‏ ‏أُمِرَ بِالْهِجْرَةِ وَأُنْزِلَ عَلَيْهِ ‏ { ‏وَقُلْ رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَلْ لِي مِنْ لَدُنْكَ سُلْطَانًا نَصِيرًا ‏}","","",""],[1848,1848,"","","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصْلُحُ قِبْلَتَانِ فِي أَرْضٍ وَلَيْسَ عَلَى مُسْلِمٍ ‏ ‏جِزْيَةٌ ‏","","",""],[1849,1849,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُغِيرَةُ بْنُ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُحْشَرُ النَّاسُ حُفَاةً عُرَاةً ‏ ‏غُرْلًا ‏ ‏فَأَوَّلُ مَنْ ‏ ‏يُكْسَى ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏ثُمَّ قَرَأَ ‏ { ‏كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ ‏}","","",""],[1850,1850,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا فَمَضْمَضَ وَقَالَ إِنَّ لَهُ دَسَمًا ‏","","",""],[1851,1851,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَةُ حَمْزَةَ ‏ ‏فَقَالَ ‏ ‏إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ‏","","",""],[1852,1852,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فِي غَيْرِ خَوْفٍ وَلَا مَطَرٍ ‏ ‏قِيلَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏وَمَا أَرَادَ إِلَى ذَلِكَ قَالَ أَرَادَ أَنْ لَا ‏ ‏يُحْرِجَ ‏ ‏أُمَّتَهُ ‏","","",""],[1853,1853,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي عَامِرٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَرِنِي الْخَاتَمَ الَّذِي بَيْنَ كَتِفَيْكَ فَإِنِّي مِنْ أَطَبِّ النَّاسِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُرِيكَ آيَةً قَالَ بَلَى قَالَ فَنَظَرَ إِلَى نَخْلَةٍ فَقَالَ ادْعُ ذَلِكَ ‏ ‏الْعِذْقَ ‏ ‏قَالَ فَدَعَاهُ فَجَاءَ ‏ ‏يَنْقُزُ ‏ ‏حَتَّى قَامَ بَيْنَ يَدَيْهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْجِعْ فَرَجَعَ إِلَى مَكَانِهِ فَقَالَ ‏ ‏الْعَامِرِيُّ ‏ ‏يَا آلَ ‏ ‏بَنِي عَامِرٍ ‏ ‏مَا رَأَيْتُ كَالْيَوْمِ رَجُلًا أَسْحَرَ ‏","","",""],[1854,1854,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مَسْعُودِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي نُصِرْتُ ‏ ‏بِالصَّبَا ‏ ‏وَإِنَّ ‏ ‏عَادًا ‏ ‏أُهْلِكَتْ ‏ ‏بِالدَّبُورِ ‏","","",""],[1855,1855,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏مَا كَذَبَ الْفُؤَادُ مَا رَأَى ‏} ‏قَالَ رَأَى ‏ ‏مُحَمَّدٌ ‏ ‏رَبَّهُ عَزَّ وَجَلَّ بِقَلْبِهِ مَرَّتَيْنِ ‏","","",""],[1856,1856,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ حُدَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ وُلِدَتْ لَهُ ابْنَةٌ فَلَمْ ‏ ‏يَئِدْهَا ‏ ‏وَلَمْ يُهِنْهَا وَلَمْ ‏ ‏يُؤْثِرْ ‏ ‏وَلَدَهُ عَلَيْهَا ‏ ‏يَعْنِي الذَّكَرَ ‏ ‏أَدْخَلَهُ اللَّهُ بِهَا الْجَنَّةَ ‏","","",""],[1857,1857,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَافَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقَامَ تِسْعَ عَشْرَةَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَنَحْنُ إِذَا سَافَرْنَا فَأَقَمْنَا تِسْعَ عَشْرَةَ صَلَّيْنَا رَكْعَتَيْنِ رَكْعَتَيْنِ فَإِذَا أَقَمْنَا أَكْثَرَ مِنْ ذَلِكَ صَلَّيْنَا أَرْبَعًا ‏","","",""],[1858,1858,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَعْتَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الطَّائِفِ ‏ ‏مَنْ خَرَجَ إِلَيْهِ مِنْ عَبِيدِ الْمُشْرِكِينَ ‏","","",""],[1859,1859,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏ ‏وَكَانَ ‏ ‏عِكْرِمَةُ ‏ ‏يَكْرَهُ بَيْعَ ‏ ‏الْفَصِيلِ ‏","","",""],[1860,1860,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الشَّيْبَانِيَّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ إِلَى أَهْلِ ‏ ‏جُرَشَ ‏ ‏يَنْهَاهُمْ أَنْ يَخْلِطُوا الزَّبِيبَ وَالتَّمْرَ ‏","","",""],[1861,1861,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى صَاحِبِ قَبْرٍ بَعْدَمَا دُفِنَ ‏","","",""],[1862,1862,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يُنْقَعُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الزَّبِيبُ قَالَ فَيَشْرَبُهُ الْيَوْمَ وَالْغَدَ وَبَعْدَ الْغَدِ إِلَى مَسَاءِ الثَّالِثَةِ ثُمَّ يُؤْمَرُ بِهِ ‏ ‏فَيُسْقَى أَوْ ‏ ‏يُهَرَاقُ ‏","","",""],[1863,1863,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَجْلَحُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَقُولُ مَا شَاءَ اللَّهُ وَشِئْتَ فَقَالَ ‏ ‏بَلْ مَا شَاءَ اللَّهُ وَحْدَهُ ‏","","",""],[1864,1864,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي فَضَاءٍ لَيْسَ بَيْنَ يَدَيْهِ شَيْءٌ ‏","","",""],[1865,1865,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدَ اللَّهِ بْنَ رَوَاحَةَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَوَافَقَ ذَلِكَ يَوْمَ الْجُمُعَةِ قَالَ فَقَدَّمَ أَصْحَابَهُ وَقَالَ أَتَخَلَّفُ ‏ ‏فَأُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ أَلْحَقُهُمْ قَالَ فَلَمَّا رَآهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَا مَنَعَكَ أَنْ ‏ ‏تَغْدُوَ ‏ ‏مَعَ أَصْحَابِكَ قَالَ فَقَالَ أَرَدْتُ أَنْ أُصَلِّيَ مَعَكَ الْجُمُعَةَ ثُمَّ أَلْحَقَهُمْ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَنْفَقْتَ مَا فِي الْأَرْضِ مَا أَدْرَكْتَ ‏ ‏غَدْوَتَهُمْ ‏","","",""],[1866,1866,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏نَجْدَةُ الْحَرُورِيُّ ‏ ‏إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَسْأَلُهُ عَنْ قَتْلِ الصِّبْيَانِ وَعَنْ ‏ ‏الْخُمُسِ ‏ ‏لِمَنْ هُوَ وَعَنْ الصَّبِيِّ مَتَى يَنْقَطِعُ عَنْهُ الْيُتْمُ وَعَنْ النِّسَاءِ هَلْ كَانَ يَخْرُجُ بِهِنَّ ‏ ‏أَوْ يَحْضُرْنَ ‏ ‏الْقِتَالَ وَعَنْ الْعَبْدِ هَلْ لَهُ فِي الْمَغْنَمِ نَصِيبٌ قَالَ فَكَتَبَ إِلَيْهِ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا الصِّبْيَانُ فَإِنْ كُنْتَ ‏ ‏الْخَضِرَ ‏ ‏تَعْرِفُ الْكَافِرَ مِنْ الْمُؤْمِنِ فَاقْتُلْهُمْ وَأَمَّا ‏ ‏الْخُمُسُ ‏ ‏فَكُنَّا نَقُولُ إِنَّهُ لَنَا فَزَعَمَ قَوْمُنَا أَنَّهُ لَيْسَ لَنَا ‏ ‏وَأَمَّا النِّسَاءُ فَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ مَعَهُ بِالنِّسَاءِ فَيُدَاوِينَ الْمَرْضَى وَيَقُمْنَ عَلَى الْجَرْحَى وَلَا يَحْضُرْنَ الْقِتَالَ وَأَمَّا الصَّبِيُّ فَيَنْقَطِعُ عَنْهُ الْيُتْمُ إِذَا احْتَلَمَ وَأَمَّا الْعَبْدُ فَلَيْسَ لَهُ مِنْ الْمَغْنَمِ نَصِيبٌ وَلَكِنَّهُ قَدْ كَانَ ‏ ‏يُرْضَخُ ‏ ‏لَهُمْ ‏","","",""],[1867,1867,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ هَذِهِ الْأَيَّامِ ‏ ‏يَعْنِي أَيَّامَ ‏ ‏الْعَشْرِ ‏ ‏قَالَ قَالُوا يَا رَسُولَ اللَّهِ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ إِلَّا رَجُلًا خَرَجَ بِنَفْسِهِ وَمَالِهِ ثُمَّ لَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَيْءٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏لَيْسَ فِيهِ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏يَعْنِي مَا مِنْ أَيَّامٍ الْعَمَلُ فِيهَا ‏","","",""],[1868,1868,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْرَأَةٌ فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ ‏ ‏أَفَأَقْضِي عَنْهَا قَالَ فَقَالَ أَرَأَيْتِ لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ أَمَا كُنْتِ تَقْضِينَهُ قَالَتْ بَلَى قَالَ فَدَيْنُ اللَّهِ عَزَّ وَجَلَّ أَحَقُّ ‏","","",""],[1869,1869,"","","‏ ‏حَدَّثَنِي ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَيْرٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَئِنْ بَقِيتُ إِلَى ‏ ‏قَابِلٍ ‏ ‏لَأَصُومَنَّ الْيَوْمَ التَّاسِعَ ‏","","",""],[1870,1870,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّتِهِ وَفِي عُمَرِهِ كُلِّهَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَالْخُلَفَاءُ ‏","","",""],[1871,1871,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو الْفُقَيْمِيُّ ‏ ‏عَنْ ‏ ‏مِهْرَانَ أَبُو صَفْوَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ ‏","","",""],[1872,1872,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدٍ يَعْنِي الْمُحَارِبِيَّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏مَهْرَانَ أَبُو صَفْوَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ ‏","","",""],[1873,1873,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عِنْدَ كُسُوفِ الشَّمْسِ ‏ ‏ثَمَانِيَ رَكَعَاتٍ وَأَرْبَعَ سَجَدَاتٍ ‏","","",""],[1874,1874,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ يَقُولُ ‏ ‏فِي الْحَرَامِ يَمِينٌ يُكَفِّرُهَا ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏وَكَتَبَ إِلَيَّ ‏ ‏يَحْيَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَانَ يَقُولُ ‏ ‏فِي الْحَرَامِ يَمِينٌ يُكَفِّرُهَا فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}","","",""],[1875,1875,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ سَالِمٍ أَبُو جَهْضَمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدًا مَأْمُورًا بَلَّغَ وَاللَّهِ مَا أُرْسِلَ بِهِ وَمَا اخْتَصَّنَا دُونَ النَّاسِ بِشَيْءٍ لَيْسَ ثَلَاثًا ‏ ‏أَمَرَنَا أَنْ ‏ ‏نُسْبِغَ ‏ ‏الْوُضُوءَ وَأَنْ لَا نَأْكُلَ ‏ ‏الصَّدَقَةَ ‏ ‏وَأَنْ لَا ‏ ‏نُنْزِيَ ‏ ‏حِمَارًا عَلَى فَرَسٍ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏فَلَقِيتُ ‏ ‏عَبْدَ اللَّهِ بْنَ حَسَنٍ ‏ ‏فَقُلْتُ إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي كَذَا وَكَذَا فَقَالَ ‏ ‏إِنَّ الْخَيْلَ كَانَتْ فِي ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَلِيلَةً فَأَحَبَّ أَنْ تَكْثُرَ فِيهِمْ ‏","","",""],[1876,1876,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ أَبِي حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَخَالِدُ بْنُ الْوَلِيدِ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏فَقَالَتْ أَلَا نُطْعِمُكُمْ مِنْ هَدِيَّةٍ أَهْدَتْهَا لَنَا ‏ ‏أُمُّ حُفَيْدٍ ‏ ‏قَالَ فَجِيءَ بِضَبَّيْنِ مَشْوِيَّيْنِ ‏ ‏فَتَبَزَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏خَالِدٌ ‏ ‏كَأَنَّكَ تَقْذَرُهُ قَالَ أَجَلْ قَالَتْ أَلَا ‏ ‏أُسْقِيكُمْ مِنْ لَبَنٍ أَهْدَتْهُ لَنَا فَقَالَ بَلَى قَالَ فَجِيءَ بِإِنَاءٍ مِنْ لَبَنٍ فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا عَنْ يَمِينِهِ ‏ ‏وَخَالِدٌ ‏ ‏عَنْ شِمَالِهِ فَقَالَ لِي الشَّرْبَةُ لَكَ وَإِنْ شِئْتَ آثَرْتَ بِهَا ‏ ‏خَالِدًا ‏ ‏فَقُلْتُ مَا كُنْتُ لِأُوثِرَ ‏ ‏بِسُؤْرِكَ ‏ ‏عَلَيَّ أَحَدًا فَقَالَ ‏ ‏مَنْ أَطْعَمَهُ اللَّهُ طَعَامًا فَلْيَقُلْ اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْرًا مِنْهُ وَمَنْ سَقَاهُ اللَّهُ لَبَنًا فَلْيَقُلْ اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ فَإِنَّهُ لَيْسَ شَيْءٌ يُجْزِئُ مَكَانَ الطَّعَامِ وَالشَّرَابِ غَيْرَ اللَّبَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُمِّ حُفَيْدٍ ‏ ‏أَهْدَتْ إِلَى أُخْتِهَا ‏ ‏مَيْمُونَةَ ‏ ‏بِضَبَّيْنِ ‏ ‏فَذَكَرَهُ ‏","","",""],[1877,1877,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَبْرَيْنِ فَقَالَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا أَحَدُهُمَا فَكَانَ لَا ‏ ‏يَسْتَنْزِهُ ‏ ‏مِنْ الْبَوْلِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏مِنْ بَوْلِهِ ‏ ‏وَأَمَّا الْآخَرُ فَكَانَ يَمْشِي ‏ ‏بِالنَّمِيمَةِ ‏ ‏ثُمَّ أَخَذَ جَرِيدَةً فَشَقَّهَا بِنِصْفَيْنِ فَغَرَزَ فِي كُلِّ قَبْرٍ وَاحِدَةً فَقَالُوا يَا رَسُولَ اللَّهِ لِمَ صَنَعْتَ هَذَا قَالَ لَعَلَّهُمَا أَنْ يُخَفَّفَ عَنْهُمَا مَا لَمْ ‏ ‏يَيْبَسَا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏تَيْبَسَا ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَائِطٍ ‏ ‏مِنْ ‏ ‏حِيطَانِ ‏ ‏الْمَدِينَةِ ‏ ‏فَسَمِعَ صَوْتَ إِنْسَانَيْنِ يُعَذَّبَانِ فِي قَبْرِهِمَا فَذَكَرَهُ وَقَالَ حَتَّى يَيْبَسَا ‏ ‏أَوْ مَا لَمْ يَيْبَسَا ‏","","",""],[1878,1878,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ وَالْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ وَقَالَ أَخْرِجُوهُمْ مِنْ ‏ ‏بُيُوتِكُمْ فَأَخْرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُلَانًا وَأَخْرَجَ ‏ ‏عُمَرُ ‏ ‏فُلَانًا ‏","","",""],[1879,1879,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏صَلَّى قَبْلَ الْخُطْبَةِ ثُمَّ خَطَبَ ‏ ‏فَيَرَى أَنَّهُ لَمْ يُسْمِعْ النِّسَاءَ فَأَتَاهُنَّ وَمَعَهُ ‏ ‏بِلَالٌ ‏ ‏نَاشِرًا ثَوْبَهُ فَوَعَظَهُنَّ وَأَمَرَهُنَّ أَنْ يَتَصَدَّقْنَ فَجَعَلَتْ الْمَرْأَةُ ‏ ‏تُلْقِي وَأَشَارَ ‏ ‏أَيُّوبُ ‏ ‏إِلَى أُذُنِهِ وَإِلَى حَلْقِهِ كَأَنَّهُ يُرِيدُ ‏ ‏التُّومَةَ ‏ ‏وَالْقِلَادَةَ ‏","","",""],[1880,1880,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْمُكَاتَبِ ‏ ‏يَعْتِقُ مِنْهُ بِقَدْرِ مَا أَدَّى ‏ ‏دِيَةَ ‏ ‏الْحُرِّ وَبِقَدْرِ مَا رَقَّ مِنْهُ ‏ ‏دِيَةَ ‏ ‏الْعَبْدِ ‏","","",""],[1881,1881,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏حَالَ ‏ ‏بَيْنَكُمْ وَبَيْنَهُ سَحَابٌ فَكَمِّلُوا ‏ ‏الْعِدَّةَ ‏ ‏ثَلَاثِينَ وَلَا تَسْتَقْبِلُوا الشَّهْرَ اسْتِقْبَالًا ‏ ‏قَالَ ‏ ‏حَاتِمٌ ‏ ‏يَعْنِي عِدَّةَ شَعْبَانَ ‏","","",""],[1882,1882,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏وَرِدْفُهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَجَالَتْ ‏ ‏بِهِ النَّاقَةُ وَهُوَ رَافِعٌ يَدَيْهِ لَا يُجَاوِزَانِ رَأْسَهُ فَسَارَ عَلَى هِينَتِهِ حَتَّى أَتَى ‏ ‏جَمْعًا ‏ ‏ثُمَّ ‏ ‏أَفَاضَ ‏ ‏الْغَدَ ‏ ‏وَرِدْفُهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏فَمَا زَالَ يُلَبِّي حَتَّى رَمَى ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏","","",""],[1883,1883,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ خَطَبَ النَّاسَ ‏ ‏بِتَبُوكَ ‏ ‏مَا فِي النَّاسِ مِثْلُ رَجُلٍ آخِذٍ بِرَأْسِ فَرَسِهِ يُجَاهِدُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَيَجْتَنِبُ شُرُورَ النَّاسِ وَمِثْلُ آخَرَ ‏ ‏بَادٍ ‏ ‏فِي نِعْمَةٍ ‏ ‏يَقْرِي ‏ ‏ضَيْفَهُ ‏ ‏وَيُعْطِي حَقَّهُ ‏","","",""],[1884,1884,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفًا ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[1885,1885,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لَبَنِ شَاةِ ‏ ‏الْجَلَّالَةِ ‏ ‏وَعَنْ ‏ ‏الْمُجَثَّمَةِ ‏ ‏وَعَنْ الشُّرْبِ مِنْ ‏ ‏فِي ‏ ‏السِّقَاءِ ‏","","",""],[1886,1886,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَ لَهُ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنْتَ ‏ ‏تُفْتِي الْحَائِضَ أَنْ تَصْدُرَ قَبْلَ أَنْ يَكُونَ آخِرُ عَهْدِهَا ‏ ‏بِالْبَيْتِ ‏ ‏قَالَ نَعَمْ قَالَ فَلَا ‏ ‏تُفْتِي بِذَلِكَ قَالَ إِمَّا لَا فَاسْأَلْ ‏ ‏فُلَانَةَ الْأَنْصَارِيَّةَ ‏ ‏هَلْ أَمَرَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَرَجَعَ ‏ ‏زَيْدٌ ‏ ‏إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَضْحَكُ فَقَالَ مَا ‏ ‏أُرَاكَ إِلَّا قَدْ صَدَقْتَ ‏","","",""],[1887,1887,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ وَإِذَا ‏ ‏اسْتُنْفِرْتُمْ ‏ ‏فَانْفِرُوا ‏","","",""],[1888,1888,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏لَا أَعْلَمُهُ إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏أَوْ ‏ ‏أَثَارَةٍ ‏ ‏مِنْ عِلْمٍ ‏} ‏قَالَ الْخَطُّ ‏","","",""],[1889,1889,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُخَوَّلٌ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الصُّبْحِ يَوْمَ الْجُمُعَةِ ‏ ‏الم تَنْزِيلُ ‏ ‏وَهَلْ أَتَى ‏ ‏وَفِي الْجُمُعَةِ بِسُورَةِ ‏ ‏الْجُمُعَةِ ‏ ‏وَإِذَا جَاءَكَ الْمُنَافِقُونَ ‏","","",""],[1890,1890,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَكَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا غَيَّرَتْ النَّارُ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[1891,1891,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سِرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَصَلَّى رَكْعَتَيْنِ لَا يَخَافُ إِلَّا اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[1892,1892,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِذَا لَمْ تُدْرِكْ الصَّلَاةَ فِي الْمَسْجِدِ كَمْ تُصَلِّي ‏ ‏بِالْبَطْحَاءِ ‏ ‏قَالَ رَكْعَتَيْنِ تِلْكَ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1893,1893,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَمْلَاهُ عَلَيَّ ‏ ‏سُفْيَانُ ‏ ‏إِلَى ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ مُرَّةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ الْمُعَلِّمُ ‏ ‏حَدَّثَنِي ‏ ‏طَلِيقُ بْنُ قَيْسٍ الْحَنَفِيُّ ‏ ‏أَخُو ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو ‏ ‏رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِي وَيَسِّرْ الْهُدَى إِلَيَّ وَانْصُرْنِي عَلَى مَنْ ‏ ‏بَغَى ‏ ‏عَلَيَّ رَبِّ اجْعَلْنِي لَكَ ‏ ‏شَكَّارًا لَكَ ‏ ‏ذَكَّارًا لَكَ ‏ ‏رَهَّابًا لَكَ مِطْوَاعًا إِلَيْكَ ‏ ‏مُخْبِتًا ‏ ‏لَكَ أَوَّاهًا ‏ ‏مُنِيبًا ‏ ‏رَبِّ تَقَبَّلْ تَوْبَتِي وَاغْسِلْ ‏ ‏حَوْبَتِي ‏ ‏وَأَجِبْ دَعْوَتِي وَثَبِّتْ حُجَّتِي وَاهْدِ قَلْبِي ‏ ‏وَسَدِّدْ ‏ ‏لِسَانِي ‏ ‏وَاسْلُلْ ‏ ‏سَخِيمَةَ ‏ ‏قَلْبِي ‏","","",""],[1894,1894,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ وَمَا صَامَ شَهْرًا تَامًّا مُنْذُ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏إِلَّا رَمَضَانَ ‏","","",""],[1895,1895,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ وَهَذِهِ سَوَاءٌ الْخِنْصَرُ وَالْإِبْهَامُ ‏","","",""],[1896,1896,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْأَخْنَسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اقْتَبَسَ رَجُلٌ عِلْمًا مِنْ النُّجُومِ إِلَّا اقْتَبَسَ بِهَا شُعْبَةً مِنْ السِّحْرِ مَا زَادَ زَادَ ‏","","",""],[1897,1897,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ هَمَّ بِحَسَنَةٍ فَعَمِلَهَا كُتِبَتْ عَشْرًا وَإِنْ لَمْ يَعْمَلْهَا كُتِبَتْ حَسَنَةً وَإِنْ هَمَّ بِسَيِّئَةٍ فَعَمِلَهَا كُتِبَتْ سَيِّئَةً وَإِنْ لَمْ يَعْمَلْهَا كُتِبَتْ حَسَنَةً ‏","","",""],[1898,1898,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏حَدَّثَنِي ‏ ‏وَهْبُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ لَحْمًا ‏ ‏أَوْ ‏ ‏عَرْقًا ‏ ‏فَصَلَّى وَلَمْ يَمَسَّ مَاءً ‏","","",""],[1899,1899,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏دَاجِنَةً ‏ ‏لِمَيْمُونَةَ ‏ ‏مَاتَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَّا انْتَفَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏أَلَّا ‏ ‏دَبَغْتُمُوهُ ‏ ‏فَإِنَّهُ ‏ ‏ذَكَاتُهُ ‏","","",""],[1900,1900,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْعِيدَ بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ ‏","","",""],[1901,1901,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏حَدَّثَنِي ‏ ‏مُسْلِمٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً قَالَتْ يَا رَسُولَ اللَّهِ إِنَّهُ كَانَ عَلَى أُمِّهَا صَوْمُ شَهْرٍ فَمَاتَتْ أَفَأَصُومُهُ عَنْهَا قَالَ ‏ ‏لَوْ كَانَ عَلَى أُمِّكِ دَيْنٌ أَكُنْتِ قَاضِيَتَهُ قَالَتْ نَعَمْ قَالَ فَدَيْنُ اللَّهِ عَزَّ وَجَلَّ أَحَقُّ أَنْ ‏ ‏يُقْضَى ‏","","",""],[1902,1902,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ وَالْمُخَنَّثِينَ مِنْ الرِّجَالَ وَقَالَ أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ قَالَ فَأَخْرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُلَانًا وَأَخْرَجَ ‏ ‏عُمَرُ ‏ ‏فُلَانًا ‏","","",""],[1903,1903,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَرِبَ لَبَنًا فَمَضْمَضَ وَقَالَ إِنَّ لَهُ دَسَمًا ‏","","",""],[1904,1904,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُلَيْمَانُ يَعْنِي الْأَعْمَشَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرِضَ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَأَتَتْهُ ‏ ‏قُرَيْشٌ ‏ ‏وَأَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ ‏ ‏وَعِنْدَ رَأْسِهِ مَقْعَدُ رَجُلٍ فَقَامَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَعَدَ فِيهِ فَقَالُوا إِنَّ ابْنَ أَخِيكَ ‏ ‏يَقَعُ ‏ ‏فِي آلِهَتِنَا قَالَ مَا شَأْنُ قَوْمِكَ يَشْكُونَكَ قَالَ يَا عَمِّ ‏ ‏أُرِيدُهُمْ عَلَى كَلِمَةٍ وَاحِدَةٍ ‏ ‏تَدِينُ ‏ ‏لَهُمْ بِهَا ‏ ‏الْعَرَبُ ‏ ‏وَتُؤَدِّي ‏ ‏الْعَجَمُ ‏ ‏إِلَيْهِمْ ‏ ‏الْجِزْيَةَ ‏ ‏قَالَ مَا هِيَ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَقَامُوا فَقَالُوا أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا قَالَ ‏ ‏وَنَزَلَ ‏ { ‏ص وَالْقُرْآنِ ذِي الذِّكْرِ ‏ ‏فَقَرَأَ حَتَّى بَلَغَ ‏ ‏إِنَّ هَذَا لَشَيْءٌ عُجَابٌ ‏} ‏و حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏فَذَكَرَ نَحْوَهُ ‏ ‏و قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏الْأَشْجَعِيُّ ‏ ‏يَحْيَى بْنُ عَبَّادٍ ‏","","",""],[1905,1905,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏عُيَيْنَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَ إِنِّي رَجُلٌ مِنْ أَهْلِ ‏ ‏خُرَاسَانَ ‏ ‏وَإِنَّ أَرْضَنَا أَرْضٌ بَارِدَةٌ فَذَكَرَ مِنْ ضُرُوبِ الشَّرَابِ فَقَالَ اجْتَنِبْ مَا أَسْكَرَ مِنْ زَبِيبٍ أَوْ تَمْرٍ أَوْ مَا سِوَى ذَلِكَ قَالَ مَا تَقُولُ فِي ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏","","",""],[1906,1906,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ الْأَخْنَسِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ أَسْوَدَ أَفْحَجَ يَنْقُضُهَا حَجَرًا حَجَرًا ‏ ‏يَعْنِي ‏ ‏الْكَعْبَةَ ‏","","",""],[1907,1907,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنِي ‏ ‏قَارِظٌ ‏ ‏عَنْ ‏ ‏أَبِي غَطَفَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏تَوَضَّأَ قَالَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَنْثِرُوا مَرَّتَيْنِ ‏ ‏بَالِغَتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[1908,1908,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ عِنْدَ ‏ ‏الْكَرْبِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْكَرِيمِ ‏","","",""],[1909,1909,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نُصِرْتُ ‏ ‏بِالصَّبَا ‏ ‏وَأُهْلِكَتْ ‏ ‏عَادٌ ‏ ‏بِالدَّبُورِ ‏","","",""],[1910,1910,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَكَحَ وَهُوَ حَرَامٌ ‏","","",""],[1911,1911,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا الشَّعْثَاءِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏مَنْ لَمْ يَجِدْ ‏ ‏إِزَارًا ‏ ‏وَوَجَدَ سَرَاوِيلَ فَلْيَلْبَسْهَا وَمَنْ لَمْ يَجِدْ نَعْلَيْنِ وَوَجَدَ خُفَّيْنِ فَلْيَلْبَسْهُمَا ‏ ‏قُلْتُ لَمْ يَقُلْ لِيَقْطَعْهُمَا قَالَ لَا ‏","","",""],[1912,1912,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْحُوَيْرِثِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبَرَّزَ فَطَعِمَ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[1913,1913,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أُنْزِلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَأَرْبَعِينَ فَمَكَثَ ‏ ‏بِمَكَّةَ ‏ ‏عَشْرًا ‏ ‏وَبِالْمَدِينَةِ ‏ ‏عَشْرًا وَقُبِضَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[1914,1914,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ ‏ ‏الصَّدَقَةَ ‏ ‏كَذَا وَكَذَا وَنِصْفَ ‏ ‏صَاعٍ ‏ ‏بُرًّا ‏","","",""],[1915,1915,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى مِنْ اللَّيْلِ ثَلَاثَ عَشْرَةَ ‏","","",""],[1916,1916,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو جَمْرَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏وَفْدَ عَبْدِ الْقَيْسِ ‏ ‏لَمَّا قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مِمَّنْ الْوَفْدُ ‏ ‏أَوْ قَالَ الْقَوْمُ ‏ ‏قَالُوا ‏ ‏رَبِيعَةُ ‏ ‏قَالَ مَرْحَبًا بِالْوَفْدِ ‏ ‏أَوْ قَالَ الْقَوْمِ ‏ ‏غَيْرَ خَزَايَا وَلَا نَدَامَى قَالُوا يَا رَسُولَ اللَّهِ أَتَيْنَاكَ مِنْ ‏ ‏شُقَّةٍ ‏ ‏بَعِيدَةٍ وَبَيْنَنَا وَبَيْنَكَ هَذَا الْحَيُّ مِنْ كُفَّارِ ‏ ‏مُضَرَ ‏ ‏وَلَسْنَا نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلَّا فِي شَهْرٍ حَرَامٍ فَأَخْبِرْنَا بِأَمْرٍ نَدْخُلُ بِهِ الْجَنَّةَ وَنُخْبِرُ بِهِ مَنْ وَرَاءَنَا وَسَأَلُوهُ عَنْ أَشْرِبَةٍ فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ ‏ ‏أَمَرَهُمْ بِالْإِيمَانِ بِاللَّهِ قَالَ أَتَدْرُونَ مَا الْإِيمَانُ بِاللَّهِ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَصَوْمُ رَمَضَانَ وَأَنْ تُعْطُوا ‏ ‏الْخُمُسَ ‏ ‏مِنْ الْمَغْنَمِ وَنَهَاهُمْ عَنْ الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏قَالَ وَرُبَّمَا قَالَ ‏ ‏وَالْمُقَيَّرِ ‏ ‏قَالَ احْفَظُوهُنَّ وَأَخْبِرُوا بِهِنَّ مَنْ وَرَاءَكُمْ ‏","","",""],[1917,1917,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو جَمْرَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جُعِلَ فِي قَبْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطِيفَةٌ ‏ ‏حَمْرَاءُ ‏","","",""],[1918,1918,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قِيلَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ فَرَغَ مِنْ ‏ ‏بَدْرٍ ‏ ‏عَلَيْكَ ‏ ‏الْعِيرَ ‏ ‏لَيْسَ دُونَهَا شَيْءٌ قَالَ فَنَادَاهُ ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏إِنَّهُ لَا يَصْلُحُ لَكَ قَالَ وَلِمَ قَالَ ‏ ‏لِأَنَّ اللَّهَ عَزَّ وَجَلَّ إِنَّمَا وَعَدَكَ إِحْدَى الطَّائِفَتَيْنِ وَقَدْ أَعْطَاكَ مَا وَعَدَكَ ‏","","",""],[1919,1919,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَجُلٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏بِنَفَرٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَسُوقُ غَنَمًا لَهُ فَسَلَّمَ عَلَيْهِمْ فَقَالُوا مَا سَلَّمَ عَلَيْنَا إِلَّا لِيَتَعَوَّذَ مِنَّا فَعَمَدُوا إِلَيْهِ فَقَتَلُوهُ وَأَتَوْا بِغَنَمِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ الْآيَةُ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا ‏ ‏ضَرَبْتُمْ ‏ ‏فِي سَبِيلِ اللَّهِ فَتَبَيَّنُوا ‏}","","",""],[1920,1920,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَجُلٌ فَسَأَلَهُ ‏ ‏وَسُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنْبَأَنِي ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏يَقُولُ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏الْمَعْنَى عَنْ قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَى ‏} ‏فَقَالَ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏قَرَابَةُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَجِلْتَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ بَطْنٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِلَّا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ قَرَابَةٌ فَنَزَلَتْ ‏ { ‏قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَى ‏} ‏إِلَّا أَنْ تَصِلُوا قَرَابَةَ مَا بَيْنِي وَبَيْنَكُمْ ‏","","",""],[1921,1921,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِامْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏سَمَّاهَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَنَسِيتُ اسْمَهَا ‏ ‏مَا مَنَعَكِ أَنْ تَحُجِّي مَعَنَا الْعَامَ قَالَتْ يَا نَبِيَّ اللَّهِ إِنَّمَا كَانَ لَنَا ‏ ‏نَاضِحَانِ ‏ ‏فَرَكِبَ أَبُو فُلَانٍ وَابْنُهُ لِزَوْجِهَا وَابْنِهَا ‏ ‏نَاضِحًا ‏ ‏وَتَرَكَ ‏ ‏نَاضِحًا ‏ ‏نَنْضَحُ ‏ ‏عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا كَانَ رَمَضَانُ فَاعْتَمِرِي فِيهِ فَإِنَّ عُمْرَةً فِيهِ تَعْدِلُ حَجَّةً ‏","","",""],[1922,1922,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏قَبَّلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مَيِّتٌ ‏","","",""],[1923,1923,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُغِيرَةُ بْنُ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحْشَرُ النَّاسُ عُرَاةً حُفَاةً ‏ ‏غُرْلًا ‏ ‏فَأَوَّلُ مَنْ ‏ ‏يُكْسَى ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏ثُمَّ قَرَأَ ‏ { ‏كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ ‏}","","",""],[1924,1924,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْحَكَمِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏و قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يُحَرِّمَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ فَلْيُحَرِّمْ النَّبِيذَ ‏","","",""],[1925,1925,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏فِطْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏رَمَلَ ‏ ‏بِالْبَيْتِ ‏ ‏وَأَنَّهَا سُنَّةٌ قَالَ صَدَقُوا وَكَذَبُوا قُلْتُ كَيْفَ صَدَقُوا وَكَذَبُوا قَالَ قَدْ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَيْتِ ‏ ‏وَلَيْسَ بِسُنَّةٍ قَدْ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ وَالْمُشْرِكُونَ عَلَى جَبَلِ ‏ ‏قُعَيْقِعَانَ ‏ ‏فَبَلَغَهُ أَنَّهُمْ يَتَحَدَّثُونَ أَنَّ بِهِمْ هَزْلًا فَأَمَرَ بِهِمْ أَنْ ‏ ‏يَرْمُلُوا ‏ ‏لِيُرِيَهُمْ أَنَّ بِهِمْ قُوَّةً ‏","","",""],[1926,1926,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏يُحَدِّثُ ‏ ‏بَعْدَمَا كَبِرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَائِرَاتِ الْقُبُورِ وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ ‏ ‏وَالسُّرُجَ ‏","","",""],[1927,1927,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْمُبَارَكِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ مُعَتِّبٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏أَبَا حَسَنٍ ‏ ‏مَوْلَى ‏ ‏أَبِي نَوْفَلٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ اسْتَفْتَى ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فِي مَمْلُوكٍ تَحْتَهُ مَمْلُوكَةٌ فَطَلَّقَهَا تَطْلِيقَتَيْنِ ثُمَّ عَتَقَا هَلْ يَصْلُحُ لَهُ أَنْ يَخْطُبَهَا قَالَ نَعَمْ قَضَى بِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1928,1928,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الَّذِي ‏ ‏يَأْتِي ‏ ‏امْرَأَتَهُ وَهِيَ حَائِضٌ يَتَصَدَّقُ بِدِينَارٍ ‏ ‏أَوْ بِنِصْفِ دِينَارٍ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَلَا ‏ ‏بَهْزٌ ‏","","",""],[1929,1929,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَكَلَّمَ يَوْمَ الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ فَهُوَ كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا وَالَّذِي يَقُولُ لَهُ أَنْصِتْ لَيْسَ لَهُ جُمُعَةٌ ‏","","",""],[1930,1930,"","","‏ ‏حَدَّثَنِي ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ النَّاسَ ‏ ‏غَضُّوا ‏ ‏مِنْ الثُّلُثِ إِلَى الرُّبُعِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الثُّلُثُ كَثِيرٌ ‏","","",""],[1931,1931,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمِنْهَالُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ رَجُلًا أَتَى ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ أُنْزِلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرًا ‏ ‏بِمَكَّةَ ‏ ‏وَعَشْرًا ‏ ‏بِالْمَدِينَةِ ‏ ‏فَقَالَ مَنْ يَقُولُ ذَلِكَ لَقَدْ ‏ ‏أُنْزِلَ عَلَيْهِ ‏ ‏بِمَكَّةَ ‏ ‏عَشْرًا وَخَمْسًا وَسِتِّينَ وَأَكْثَرَ ‏","","",""],[1932,1932,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏فُضَيْلٌ يَعْنِي ابْنَ غَزْوَانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ يَا أَيُّهَا النَّاسُ أَيُّ يَوْمٍ هَذَا قَالُوا هَذَا يَوْمٌ حَرَامٌ قَالَ أَيُّ بَلَدٍ هَذَا قَالُوا بَلَدٌ حَرَامٌ قَالَ فَأَيُّ شَهْرٍ هَذَا قَالُوا شَهْرٌ حَرَامٌ قَالَ ‏ ‏إِنَّ أَمْوَالَكُمْ وَدِمَاءَكُمْ وَأَعْرَاضَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا ثُمَّ أَعَادَهَا مِرَارًا ثُمَّ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ فَقَالَ اللَّهُمَّ هَلْ بَلَّغْتُ مِرَارًا ‏ ‏قَالَ يَقُولُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَاللَّهِ إِنَّهَا لَوَصِيَّةٌ إِلَى رَبِّهِ عَزَّ وَجَلَّ ‏ ‏ثُمَّ قَالَ أَلَا فَلْيُبَلِّغْ الشَّاهِدُ الْغَائِبَ لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[1933,1933,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ مُسْلِمٍ الطَّحَّانُ الصَّغِيرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِكْرِمَةَ ‏ ‏يَرْفَعُ الْحَدِيثَ فِيمَا أُرَى إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ الْحَيَّاتِ مَخَافَةَ طَلَبِهِنَّ فَلَيْسَ مِنَّا مَا سَالَمْنَاهُنَّ مُنْذُ حَارَبْنَاهُنَّ ‏","","",""],[1934,1934,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الْفَجْرِ فِي أَوَّلِ رَكْعَةٍ ‏ { ‏آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى ‏ ‏إِبْرَاهِيمَ ‏ } ‏إِلَى آخِرِ الْآيَةِ وَفِي الرَّكْعَةِ الثَّانِيَةِ ‏ { ‏آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ ‏}","","",""],[1935,1935,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ كِنَانَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مُتَخَشِّعًا مُتَضَرِّعًا مُتَوَاضِعًا ‏ ‏مُتَبَذِّلًا ‏ ‏مُتَرَسِّلًا ‏ ‏فَصَلَّى بِالنَّاسِ رَكْعَتَيْنِ كَمَا ‏ ‏يُصَلِّي فِي الْعِيدِ لَمْ يَخْطُبْ كَخُطْبَتِكُمْ هَذِهِ ‏","","",""],[1936,1936,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏خَرَجَ ‏ ‏عَلِيٌّ ‏ ‏بِابْنَةِ حَمْزَةَ ‏ ‏فَاخْتَصَمَ فِيهَا ‏ ‏عَلِيٌّ ‏ ‏وَجَعْفَرٌ ‏ ‏وَزَيْدٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏ابْنَةُ عَمِّي وَأَنَا أَخْرَجْتُهَا وَقَالَ ‏ ‏جَعْفَرٌ ‏ ‏ابْنَةُ عَمِّي وَخَالَتُهَا عِنْدِي وَقَالَ ‏ ‏زَيْدٌ ‏ ‏ابْنَةُ أَخِي وَكَانَ ‏ ‏زَيْدٌ ‏ ‏مُؤَاخِيًا ‏ ‏لِحَمْزَةَ ‏ ‏آخَى بَيْنَهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِزَيْدٍ ‏ ‏أَنْتَ مَوْلَايَ وَمَوْلَاهَا وَقَالَ ‏ ‏لِعَلِيٍّ ‏ ‏أَنْتَ أَخِي وَصَاحِبِي وَقَالَ ‏ ‏لِجَعْفَرٍ ‏ ‏أَشْبَهْتَ خَلْقِي وَخُلُقِي وَهِيَ إِلَى خَالَتِهَا ‏","","",""],[1937,1937,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ بَيْعِ الْخَمْرِ فَقَالَ كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدِيقٌ مِنْ ‏ ‏ثَقِيفٍ ‏ ‏أَوْ مِنْ ‏ ‏دَوْسٍ ‏ ‏فَلَقِيَهُ ‏ ‏بِمَكَّةَ ‏ ‏عَامَ الْفَتْحِ ‏ ‏بِرَاوِيَةِ ‏ ‏خَمْرٍ ‏ ‏يُهْدِيهَا إِلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَبَا فُلَانٍ ‏ ‏أَمَا عَلِمْتَ أَنَّ اللَّهَ حَرَّمَهَا فَأَقْبَلَ ‏ ‏الرَّجُلُ ‏ ‏عَلَى غُلَامِهِ فَقَالَ اذْهَبْ فَبِعْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا أَبَا فُلَانٍ بِمَاذَا أَمَرْتَهُ قَالَ أَمَرْتُهُ أَنْ يَبِيعَهَا قَالَ إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا فَأَمَرَ بِهَا فَأُفْرِغَتْ فِي ‏ ‏الْبَطْحَاءِ ‏","","",""],[1938,1938,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْرِضُ الْكِتَابَ عَلَى ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فِي كُلِّ رَمَضَانَ فَإِذَا أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلَةِ الَّتِي يَعْرِضُ فِيهَا مَا يَعْرِضُ أَصْبَحَ وَهُوَ أَجْوَدُ مِنْ الرِّيحِ الْمُرْسَلَةِ لَا يُسْأَلُ عَنْ شَيْءٍ إِلَّا أَعْطَاهُ فَلَمَّا كَانَ فِي الشَّهْرِ الَّذِي هَلَكَ بَعْدَهُ عَرَضَ عَلَيْهِ عَرْضَتَيْنِ ‏","","",""],[1939,1939,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِجِبْرِيلَ ‏ ‏مَا يَمْنَعُكَ أَنْ تَزُورَنَا أَكْثَرَ مِمَّا تَزُورُنَا قَالَ فَنَزَلَتْ ‏ { ‏وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[1940,1940,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏حَضَرْنَا مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏جَنَازَةَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَرِفَ ‏ ‏قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏هَذِهِ ‏ ‏مَيْمُونَةُ ‏ ‏إِذَا رَفَعْتُمْ نَعْشَهَا فَلَا تُزَعْزِعُوهَا وَلَا تُزَلْزِلُوهَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏عِنْدَهُ تِسْعُ نِسْوَةٍ وَكَانَ يَقْسِمُ لِثَمَانٍ وَوَاحِدَةٌ لَمْ يَكُنْ لِيَقْسِمَ لَهَا ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏الَّتِي لَمْ يَكُنْ يَقْسِمُ لَهَا ‏ ‏صَفِيَّةُ ‏","","",""],[1941,1941,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَكْثَرُ مَا ‏ ‏يُصَلِّي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَ الْفَجْرِ ‏ { ‏آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَإِسْمَاعِيلَ ‏ } ‏إِلَى آخِرِ الْآيَةِ وَالْأُخْرَى ‏ { ‏آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ ‏}","","",""],[1942,1942,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ صَوْمِ رَجَبٍ كَيْفَ ‏ ‏تَرَى ‏ ‏فِيهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ ‏","","",""],[1943,1943,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏أَكْحَالِكُمُ ‏ ‏الْإِثْمِدُ ‏ ‏يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعَرَ ‏","","",""],[1944,1944,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏لَقِيَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَقَالَ تَزَوَّجْتَ قَالَ قُلْتُ لَا قَالَ تَزَوَّجْ ثُمَّ لَقِيَنِي بَعْدَ ذَلِكَ فَقَالَ تَزَوَّجْتَ قَالَ قُلْتُ لَا قَالَ ‏ ‏تَزَوَّجْ فَإِنَّ خَيْرَ هَذِهِ ‏ ‏الْأُمَّةِ أَكْثَرُهَا ‏ ‏نِسَاءً ‏","","",""],[1945,1945,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرْسَلْتَ الْكَلْبَ فَأَكَلَ مِنْ الصَّيْدِ فَلَا تَأْكُلْ فَإِنَّمَا أَمْسَكَ عَلَى نَفْسِهِ وَإِذَا أَرْسَلْتَهُ فَقَتَلَ وَلَمْ يَأْكُلْ فَكُلْ فَإِنَّمَا أَمْسَكَ عَلَى صَاحِبِهِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَكَانَ فِي كِتَابِ أَبِي عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَضَرَبَ ‏ ‏عَلَيْهِ أَبِي كَذَا قَالَ ‏ ‏أَسْبَاطٌ ‏","","",""],[1946,1946,"","","‏ ‏حَدَّثَنَا ‏ ‏شُجَاعُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي جَنَابٍ الْكَلْبِيِّ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ثَلَاثٌ هُنَّ عَلَيَّ فَرَائِضُ وَهُنَّ لَكُمْ تَطَوُّعٌ ‏ ‏الْوَتْرُ ‏ ‏وَالنَّحْرُ وَصَلَاةُ الضُّحَى ‏","","",""],[1947,1947,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ سُلَيْمَانُ بْنُ حَيَّانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَعْمَشَ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏مُزْدَلِفَةَ ‏ ‏قَبْلَ طُلُوعِ الشَّمْسِ ‏","","",""],[1948,1948,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوهَا ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ فِي تَاسِعَةٍ تَبْقَى أَوْ خَامِسَةٍ تَبْقَى أَوْ سَابِعَةٍ تَبْقَى ‏","","",""],[1949,1949,"","","‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا قَاتَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا حَتَّى يَدْعُوَهُمْ ‏","","",""],[1950,1950,"","","‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ بَنَاتَهُ وَنِسَاءَهُ أَنْ يَخْرُجْنَ فِي الْعِيدَيْنِ ‏","","",""],[1951,1951,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَرْقَمِ بْنِ شُرَحْبِيلَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ بِالنَّاسِ ثُمَّ وَجَدَ خِفَّةً فَخَرَجَ فَلَمَّا أَحَسَّ بِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَرَادَ أَنْ ‏ ‏يَنْكُصَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَلَسَ إِلَى جَنْبِ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ يَسَارِهِ وَاسْتَفْتَحَ مِنْ الْآيَةِ الَّتِي انْتَهَى إِلَيْهَا ‏ ‏أَبُو بَكْرٍ ‏","","",""],[1952,1952,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَى الْجَمْرَةَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏يَوْمَ النَّحْرِ رَاكِبًا ‏","","",""],[1953,1953,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَا تَعِبْ عَلَى مَنْ صَامَ فِي السَّفَرِ وَلَا عَلَى مَنْ أَفْطَرَ قَدْ ‏ ‏صَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السَّفَرِ وَأَفْطَرَ ‏","","",""],[1954,1954,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏أَوْ غَيْرِهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى قَرْيَةٍ عَلَى رَأْسِ أَرْبَعَةِ ‏ ‏فَرَاسِخَ ‏ ‏أَوْ قَالَ ‏ ‏فَرْسَخَيْنِ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏فَأَمَرَ مَنْ أَكَلَ أَنْ لَا يَأْكُلَ بَقِيَّةَ يَوْمِهِ وَمَنْ لَمْ يَأْكُلْ أَنْ يُتِمَّ صَوْمَهُ ‏","","",""],[1955,1955,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا جَاءَ مُسْلِمًا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَاءَتْ امْرَأَتُهُ مُسْلِمَةً بَعْدَهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهَا أَسْلَمَتْ مَعِي فَرَدَّهَا عَلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1956,1956,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي جَهْضَمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِسْبَاغِ ‏ ‏الْوُضُوءِ ‏","","",""],[1957,1957,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَسَلَمَةَ بْنِ وَهْرَامٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى بِسَاطٍ ‏","","",""],[1958,1958,"","","‏ ‏حَدَّثَنِي ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَشَهِدْتَ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ وَلَوْلَا مَكَانِي مِنْهُ مَا شَهِدْتُهُ لِصِغَرِي قَالَ خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى عِنْدَ دَارِ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏رَكْعَتَيْنِ ثُمَّ خَطَبَ لَمْ يَذْكُرْ أَذَانًا وَلَا إِقَامَةً ‏","","",""],[1959,1959,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي الْجَهْمِ بْنِ صُخَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ ‏ ‏بِذِي قَرَدٍ ‏ ‏أَرْضٍ مِنْ أَرْضِ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏فَصَفَّ النَّاسُ خَلْفَهُ صَفَّيْنِ صَفٌّ مُوَازِي الْعَدُوِّ وَصَفٌّ خَلْفَهُ فَصَلَّى بِالصَّفِّ الَّذِي يَلِيهِ رَكْعَةً ثُمَّ ‏ ‏نَكَصَ ‏ ‏هَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ فَصَلَّى بِهِمْ رَكْعَةً أُخْرَى ‏","","",""],[1960,1960,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏طَاوُسًا ‏ ‏عَنْ ‏ ‏السُّبْحَةِ ‏ ‏فِي السَّفَرِ قَالَ وَكَانَ ‏ ‏الْحَسَنُ بْنُ مُسْلِمِ بْنِ يَنَّاقٍ ‏ ‏جَالِسًا ‏ ‏فَقَالَ ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏وَطَاوُسٌ ‏ ‏يَسْمَعُ ‏ ‏حَدَّثَنَا ‏ ‏طَاوُسٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْحَضَرِ وَالسَّفَرِ فَكَمَا تُصَلِّي فِي الْحَضَرِ قَبْلَهَا وَبَعْدَهَا فَصَلِّ فِي السَّفَرِ قَبْلَهَا وَبَعْدَهَا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً وَصَلِّهَا فِي السَّفَرِ ‏","","",""],[1961,1961,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ بِرَكْعَتَيْ الضُّحَى ‏ ‏وَبِالْوَتْرِ ‏ ‏وَلَمْ يُكْتَبْ ‏","","",""],[1962,1962,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا قَرَأَ ‏ { ‏سَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏} ‏قَالَ سُبْحَانَ ‏ ‏رَبِّيَ الْأَعْلَى ‏","","",""],[1963,1963,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ وَهْرَامٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَادِي عُسْفَانَ ‏ ‏حِينَ حَجَّ قَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَيُّ وَادٍ هَذَا قَالَ ‏ ‏وَادِي عُسْفَانَ ‏ ‏قَالَ لَقَدْ مَرَّ بِهِ ‏ ‏هُودٌ ‏ ‏وَصَالِحٌ ‏ ‏عَلَى ‏ ‏بَكَرَاتٍ ‏ ‏حُمْرٍ ‏ ‏خُطُمُهَا ‏ ‏اللِّيفُ ‏ ‏أُزُرُهُمْ ‏ ‏الْعَبَاءُ وَأَرْدِيَتُهُمْ ‏ ‏النِّمَارُ ‏ ‏يُلَبُّونَ يَحُجُّونَ ‏ ‏الْبَيْتَ الْعَتِيقَ ‏","","",""],[1964,1964,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُنْبَذُ ‏ ‏لَهُ لَيْلَةَ الْخَمِيسِ فَيَشْرَبُهُ يَوْمَ الْخَمِيسِ وَيَوْمَ الْجُمُعَةِ ‏ ‏قَالَ وَأُرَاهُ قَالَ وَيَوْمَ السَّبْتِ ‏ ‏فَإِذَا كَانَ عِنْدَ الْعَصْرِ فَإِنْ بَقِيَ مِنْهُ شَيْءٌ سَقَاهُ الْخَدَمَ أَوْ أَمَرَ بِهِ ‏ ‏فَأُهْرِيقَ ‏","","",""],[1965,1965,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ فِي الْقُرْآنِ بِغَيْرِ عِلْمٍ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[1966,1966,"","","‏ ‏حَدَّثَنِي ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏آدَمَ بْنِ سُلَيْمَانَ ‏ ‏مَوْلَى ‏ ‏خَالِدِ بْنِ خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏} ‏قَالَ دَخَلَ قُلُوبَهُمْ مِنْهَا شَيْءٌ لَمْ يَدْخُلْ قُلُوبَهُمْ مِنْ شَيْءٍ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا وَسَلَّمْنَا فَأَلْقَى اللَّهُ الْإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ‏} ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏آدَمُ ‏ ‏هَذَا هُوَ ‏ ‏أَبُو يَحْيَى بْنُ آدَمَ ‏","","",""],[1967,1967,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبْدِ اللَّهِ بْنِ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي مَعْبَدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَعَثَ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏قَالَ ‏ ‏إِنَّكَ تَأْتِي قَوْمًا ‏ ‏أَهْلَ كِتَابٍ ‏ ‏فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ فَإِنْ هُمْ أَطَاعُوكَ لِذَلِكَ فَأَعْلِمْهُمْ أَنَّ اللَّهَ عَزَّ وَجَلَّ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَإِنْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أَنَّ اللَّهَ عَزَّ وَجَلَّ افْتَرَضَ عَلَيْهِمْ ‏ ‏صَدَقَةً ‏ ‏فِي أَمْوَالِهِمْ تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ وَتُرَدُّ فِي فُقَرَائِهِمْ فَإِنْ هُمْ أَطَاعُوكَ لِذَلِكَ فَإِيَّاكَ ‏ ‏وَكَرَائِمَ ‏ ‏أَمْوَالِهِمْ وَاتَّقِ دَعْوَةَ الْمَظْلُومِ فَإِنَّهَا لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ حِجَابٌ ‏","","",""],[1968,1968,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّةً مَرَّةً ‏","","",""],[1969,1969,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَجَدَ يُرَى بَيَاضُ إِبْطَيْهِ ‏","","",""],[1970,1970,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ سُلَيْمَانَ بْنِ الْغَسِيلِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ النَّاسَ وَعَلَيْهِ ‏ ‏عِصَابَةٌ ‏ ‏دَسِمَةٌ ‏","","",""],[1971,1971,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَصَفْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏فَاطِمَةَ بِنْتِ حُسَيْنٍ ‏ ‏أَنَّهَا سَمِعَتِ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُدِيمُوا إِلَى ‏ ‏الْمَجْذُومِينَ ‏ ‏النَّظَرَ ‏","","",""],[1972,1972,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَدِدْتُ أَنَّ النَّاسَ ‏ ‏غَضُّوا ‏ ‏مِنْ الثُّلُثِ إِلَى الرُّبُعِ فِي الْوَصِيَّةِ لِأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الثُّلُثُ كَثِيرٌ ‏ ‏أَوْ كَبِيرٌ ‏","","",""],[1973,1973,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ وَاثِلَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏رَمَلَ ‏ ‏وَأَنَّهَا سُنَّةٌ قَالَ صَدَقَ قَوْمِي وَكَذَبُوا قَدْ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَيْسَتْ بِسُنَّةٍ وَلَكِنَّهُ قَدِمَ وَالْمُشْرِكُونَ عَلَى جَبَلِ ‏ ‏قُعَيْقِعَانَ ‏ ‏فَتَحَدَّثُوا أَنَّ بِهِ وَبِأَصْحَابِهِ هَزْلًا وَجَهْدًا وَشِدَّةً فَأَمَرَ بِهِمْ ‏ ‏فَرَمَلُوا ‏ ‏بِالْبَيْتِ ‏ ‏لِيُرِيَهُمْ أَنَّهُمْ لَمْ يُصِبْهُمْ ‏ ‏جَهْدٌ ‏","","",""],[1974,1974,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ذَرٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِجِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَلَا تَزُورُنَا أَكْثَرَ مِمَّا تَزُورُنَا فَنَزَلَتْ ‏ { ‏وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[1975,1975,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْدَى فِي ‏ ‏بُدْنِهِ ‏ ‏جَمَلًا كَانَ ‏ ‏لِأَبِي جَهْلٍ ‏ ‏بُرَتُهُ ‏ ‏فِضَّةٌ ‏","","",""],[1976,1976,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِجُبْنَةٍ قَالَ فَجَعَلَ أَصْحَابُهُ يَضْرِبُونَهَا بِالْعِصِيِّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَعُوا السِّكِّينَ وَاذْكُرُوا اسْمَ اللَّهِ وَكُلُوا ‏","","",""],[1977,1977,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏وَعَطَاءٍ ‏ ‏قَالَا ‏ ‏الْأُضْحِيَّةُ ‏ ‏سُنَّةٌ ‏ ‏وَقَالَ ‏ ‏عِكْرِمَةُ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ بِالْأُضْحِيَّةِ ‏ ‏وَالْوَتْرِ ‏ ‏وَلَمْ ‏ ‏تُكْتَبْ ‏","","",""],[1978,1978,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَمِسْعَرٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُغَيْلِمَةَ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏عَلَى حُمُرَاتٍ لَنَا مِنْ ‏ ‏جَمْعٍ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏بِلَيْلٍ ‏ ‏فَجَعَلَ ‏ ‏يَلْطَحُ ‏ ‏أَفْخَاذَنَا وَيَقُولُ ‏ ‏أُبَيْنَى ‏ ‏لَا تَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏وَزَادَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا إِخَالُ أَحَدًا ‏ ‏يَعْقِلُ ‏ ‏يَرْمِي حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[1979,1979,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِي اللَّيْلِ فَقَضَى حَاجَتَهُ ثُمَّ غَسَلَ وَجْهَهُ وَيَدَيْهِ ثُمَّ جَاءَ فَنَامَ ‏","","",""],[1980,1980,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَامَ حَتَّى ‏ ‏نَفَخَ ‏ ‏ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[1981,1981,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ يَعْنِي الْعُرَنِيَّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا نَدْرِ أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ وَلَكِنَّا نَقْرَأُ ‏","","",""],[1982,1982,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ نَجِيحٍ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اطَّلَعْتُ فِي الْجَنَّةِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا الْفُقَرَاءَ وَاطَّلَعْتُ فِي النَّارِ فَرَأَيْتُ أَكْثَرَ أَهْلِهَا النِّسَاءَ ‏","","",""],[1983,1983,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنَّا ‏ ‏نُخَابِرُ ‏ ‏وَلَا نَرَى بِذَلِكَ بَأْسًا ‏ ‏حَتَّى زَعَمَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏ذَكَرْتُهُ ‏ ‏لِطَاوُسٍ ‏ ‏فَقَالَ ‏ ‏طَاوُسٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْنَحُ أَحَدُكُمْ أَخَاهُ الْأَرْضَ خَيْرٌ لَهُ مِنْ أَنْ يَأْخُذَ لَهَا خَرَاجًا مَعْلُومًا ‏","","",""],[1984,1984,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَ تَحْرِيمُ الْخَمْرِ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ بِإِخْوَانِنَا الَّذِينَ مَاتُوا وَهُمْ يَشْرَبُونَهَا فَنَزَلَتْ ‏ { ‏لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ ‏ ‏جُنَاحٌ ‏ ‏فِيمَا طَعِمُوا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏","","",""],[1985,1985,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُغَيْلِمَةَ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏بِلَيْلٍ عَلَى حُمُرَاتٍ لَنَا فَجَعَلَ ‏ ‏يَلْطَحُ ‏ ‏أَفْخَاذَنَا وَيَقُولُ ‏ ‏أُبَيْنَى ‏ ‏لَا تَرْمُوا الْجَمْرَةَ حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[1986,1986,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ الْعُرَنِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَمَيْتُمْ الْجَمْرَةَ فَقَدْ حَلَّ لَكُمْ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ فَقَالَ رَجُلٌ وَالطِّيبُ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا أَنَا فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَمِّخُ رَأْسَهُ بِالْمِسْكِ أَفَطِيبٌ ذَاكَ أَمْ لَا ‏","","",""],[1987,1987,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْأَخْدَعَيْنِ ‏ ‏وَبَيْنَ الْكَتِفَيْنِ ‏","","",""],[1988,1988,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي جَهْضَمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نُنْزِيَ ‏ ‏حِمَارًا عَلَى فَرَسٍ ‏","","",""],[1989,1989,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَدِمَتْ ‏ ‏عِيرٌ ‏ ‏الْمَدِينَةَ ‏ ‏فَاشْتَرَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا ‏ ‏فَرَبِحَ ‏ ‏أَوَاقِيَّ ‏ ‏فَقَسَمَهَا فِي أَرَامِلِ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏وَقَالَ ‏ ‏لَا ‏ ‏أَشْتَرِي شَيْئًا لَيْسَ عِنْدِي ثَمَنُهُ ‏","","",""],[1990,1990,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ حَبْتَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ مَهْرِ ‏ ‏الْبَغِيِّ ‏ ‏وَثَمَنِ الْكَلْبِ وَثَمَنِ الْخَمْرِ ‏","","",""],[1991,1991,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَجَاءَتْ ‏ ‏جَارِيَتَانِ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏حَتَّى أَخَذَتَا بِرُكْبَتَيْهِ ‏ ‏فَفَرَّعَ ‏ ‏بَيْنَهُمَا ‏","","",""],[1992,1992,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَوْعِظَةٍ فَقَالَ ‏ ‏إِنَّكُمْ مَحْشُورُونَ إِلَى اللَّهِ تَعَالَى حُفَاةً عُرَاةً ‏ ‏غُرْلًا ‏ { ‏كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ ‏} ‏فَأَوَّلُ الْخَلَائِقِ ‏ ‏يُكْسَى ‏ ‏إِبْرَاهِيمُ خَلِيلُ الرَّحْمَنِ ‏ ‏عَزَّ وَجَلَّ قَالَ ثُمَّ يُؤْخَذُ بِقَوْمٍ مِنْكُمْ ذَاتَ الشِّمَالِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏وَإِنَّهُ سَيُجَاءُ بِرِجَالٍ مِنْ أُمَّتِي فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ ‏ ‏فَأَقُولُ يَا رَبِّ أَصْحَابِي قَالَ فَيُقَالُ لِي إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ لَمْ يَزَالُوا مُرْتَدِّينَ عَلَى ‏ ‏أَعْقَابِهِمْ ‏ ‏مُذْ فَارَقْتَهُمْ فَأَقُولُ كَمَا قَالَ الْعَبْدُ الصَّالِحُ ‏ { ‏وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ ‏ ‏الْآيَةَ إِلَى ‏ ‏إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ‏}","","",""],[1993,1993,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏ذَرِّ بْنِ عَبْدِ اللَّهِ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُحَدِّثُ نَفْسِي بِالشَّيْءِ لَأَنْ ‏ ‏أَخِرَّ ‏ ‏مِنْ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَتَكَلَّمَ بِهِ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ الْحَمْدُ لِلَّهِ الَّذِي رَدَّ كَيَدَهُ إِلَى الْوَسْوَسَةِ ‏","","",""],[1994,1994,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اخْتَلَفْتُمْ فِي الطَّرِيقِ فَاجْعَلُوهُ سَبْعَ أَذْرُعٍ وَمَنْ بَنَى بِنَاءً فَلْيَدْعَمْهُ حَائِطَ جَارِهِ ‏","","",""],[1995,1995,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏فَسَارَعَ قَوْمٌ فَقَالَ ‏ ‏امْتَدُّوا وَسُدُّوا لَيْسَ ‏ ‏الْبِرُّ ‏ ‏بِإِيضَاعِ الْخَيْلِ وَلَا الرِّكَابِ ‏ ‏قَالَ ‏ ‏فَمَا رَأَيْتُ رَافِعَةً يَدَهَا تَعْدُو حَتَّى أَتَيْنَا ‏ ‏جَمْعًا ‏","","",""],[1996,1996,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَاءُ لَا يُنَجِّسُهُ شَيْءٌ ‏","","",""],[1997,1997,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً مِنْ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْتَسَلَتْ مِنْ جَنَابَةٍ فَاغْتَسَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ تَوَضَّأَ ‏ ‏مِنْ ‏ ‏فَضْلِهَا ‏","","",""],[1998,1998,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ بَعْضَ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْتَسَلَتْ مِنْ الْجَنَابَةِ فَتَوَضَّأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِفَضْلِهِ ‏ ‏فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ ‏ ‏إِنَّ الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ ‏","","",""],[1999,1999,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ أَبُو سَعِيدٍ الْعَنْقَزِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏هَجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ شَهْرًا فَلَمَّا مَضَى تِسْعٌ وَعِشْرُونَ أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏فَقَالَ قَدْ ‏ ‏بَرَّتْ يَمِينُكَ وَقَدْ تَمَّ الشَّهْرُ ‏","","",""],[2000,2000,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏فِطْرٍ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ ثَنَا ‏ ‏فِطْرٌ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ أَبِي سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ لَهُ أُخْتَانِ فَأَحْسَنَ صُحْبَتَهُمَا مَا صَحِبَتَاهُ دَخَلَ بِهِمَا الْجَنَّةَ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏تُدْرِكُ لَهُ ‏ ‏ابْنَتَانِ فَأَحْسَنَ إِلَيْهِمَا مَا صَحِبَتَاهُ إِلَّا أَدْخَلَهُ اللَّهُ تَعَالَى الْجَنَّةَ ‏","","",""]];
